package repository

import (
	"context"
	"database/sql"
	"errors"
	"fmt"

	"github.com/coderkamlesh/portfolio_api/internal/database"
	"github.com/coderkamlesh/portfolio_api/internal/models"
)

// ProfileRepository reads and writes the singleton profile_details row.
type ProfileRepository struct {
	base
}

// NewProfileRepository binds the repository to the database connection.
func NewProfileRepository(db *database.DB) *ProfileRepository {
	return &ProfileRepository{base{db: db}}
}

const profileColumns = `id, singleton_key, full_name, title, tagline, summary, email, phone,
	location, avatar_url, linkedin_url, github_url, portfolio_url, twitter_url,
	resume_file_url, career_gap_note, experience_level, updated_at`

// Find loads the singleton profile, or models.ErrNotFound when it has not been
// populated yet.
func (r *ProfileRepository) Find(ctx context.Context) (*models.Profile, error) {
	p, err := scanProfile(r.db.QueryRowContext(ctx, `SELECT `+profileColumns+` FROM profile_details WHERE singleton_key = 1`))
	if err != nil {
		return nil, notFound(err)
	}
	return p, nil
}

// Upsert creates the singleton profile or replaces every editable field of the
// existing row. The row ID is preserved on update.
func (r *ProfileRepository) Upsert(ctx context.Context, p *models.Profile) error {
	const q = `INSERT INTO profile_details (
		id, singleton_key, full_name, title, tagline, summary, email, phone, location,
		avatar_url, linkedin_url, github_url, portfolio_url, twitter_url,
		resume_file_url, career_gap_note, experience_level, updated_at
	) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
	ON CONFLICT(singleton_key) DO UPDATE SET
		full_name = excluded.full_name,
		title = excluded.title,
		tagline = excluded.tagline,
		summary = excluded.summary,
		email = excluded.email,
		phone = excluded.phone,
		location = excluded.location,
		avatar_url = excluded.avatar_url,
		linkedin_url = excluded.linkedin_url,
		github_url = excluded.github_url,
		portfolio_url = excluded.portfolio_url,
		twitter_url = excluded.twitter_url,
		resume_file_url = excluded.resume_file_url,
		career_gap_note = excluded.career_gap_note,
		experience_level = excluded.experience_level,
		updated_at = excluded.updated_at`

	_, err := r.db.ExecContext(ctx, q,
		p.ID, p.SingletonKey, p.FullName, p.Title, nullString(p.Tagline), nullString(p.Summary),
		p.Email, nullString(p.Phone), nullString(p.Location), nullString(p.AvatarURL),
		nullString(p.LinkedinURL), nullString(p.GithubURL), nullString(p.PortfolioURL),
		nullString(p.TwitterURL), nullString(p.ResumeFileURL), nullString(p.CareerGapNote),
		nullString(p.ExperienceLevel), database.FormatTime(p.UpdatedAt),
	)
	if err != nil {
		return fmt.Errorf("profile: upsert: %w", err)
	}
	return nil
}

func scanProfile(row rowScanner) (*models.Profile, error) {
	var (
		p               models.Profile
		singletonKey    sql.NullInt64
		tagline         sql.NullString
		summary         sql.NullString
		phone           sql.NullString
		location        sql.NullString
		avatarURL       sql.NullString
		linkedinURL     sql.NullString
		githubURL       sql.NullString
		portfolioURL    sql.NullString
		twitterURL      sql.NullString
		resumeFileURL   sql.NullString
		careerGapNote   sql.NullString
		experienceLevel sql.NullString
		updatedAt       string
	)
	if err := row.Scan(
		&p.ID, &singletonKey, &p.FullName, &p.Title, &tagline, &summary, &p.Email,
		&phone, &location, &avatarURL, &linkedinURL, &githubURL, &portfolioURL,
		&twitterURL, &resumeFileURL, &careerGapNote, &experienceLevel, &updatedAt,
	); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, models.ErrNotFound
		}
		return nil, fmt.Errorf("profile: scan: %w", err)
	}

	p.SingletonKey = int(singletonKey.Int64)
	p.Tagline = tagline.String
	p.Summary = summary.String
	p.Phone = phone.String
	p.Location = location.String
	p.AvatarURL = avatarURL.String
	p.LinkedinURL = linkedinURL.String
	p.GithubURL = githubURL.String
	p.PortfolioURL = portfolioURL.String
	p.TwitterURL = twitterURL.String
	p.ResumeFileURL = resumeFileURL.String
	p.CareerGapNote = careerGapNote.String
	p.ExperienceLevel = experienceLevel.String

	var err error
	if p.UpdatedAt, err = database.ParseTime(updatedAt); err != nil {
		return nil, fmt.Errorf("profile: parse updated_at: %w", err)
	}
	return &p, nil
}

package service

import (
	"context"
	"errors"
	"strings"
	"time"

	"github.com/coderkamlesh/portfolio_api/internal/models"
	"github.com/coderkamlesh/portfolio_api/internal/pkg/ids"
)

const singletonProfileKey = 1

// ProfileDeps wires the profile service to persistence. Now is injectable for
// deterministic tests; it defaults to UTC time.
type ProfileDeps struct {
	Profiles ProfileStore
	Now      func() time.Time
}

// ProfileService owns the singleton portfolio profile use-cases.
type ProfileService struct {
	profiles ProfileStore
	now      func() time.Time
}

// NewProfileService builds the service.
func NewProfileService(deps ProfileDeps) *ProfileService {
	now := deps.Now
	if now == nil {
		now = func() time.Time { return time.Now().UTC() }
	}
	return &ProfileService{profiles: deps.Profiles, now: now}
}

// ProfileInput is the full replacement payload accepted by the admin profile
// endpoint. Empty optional strings clear their columns.
type ProfileInput struct {
	FullName        string
	Title           string
	Tagline         string
	Summary         string
	Email           string
	Phone           string
	Location        string
	AvatarURL       string
	LinkedinURL     string
	GithubURL       string
	PortfolioURL    string
	TwitterURL      string
	ResumeFileURL   string
	CareerGapNote   string
	ExperienceLevel string
}

// PublicProfileView is exposed to visitors of the portfolio site.
type PublicProfileView struct {
	FullName        string `json:"full_name"`
	Title           string `json:"title"`
	Tagline         string `json:"tagline,omitempty"`
	Summary         string `json:"summary,omitempty"`
	Email           string `json:"email"`
	Phone           string `json:"phone,omitempty"`
	Location        string `json:"location,omitempty"`
	AvatarURL       string `json:"avatar_url,omitempty"`
	LinkedinURL     string `json:"linkedin_url,omitempty"`
	GithubURL       string `json:"github_url,omitempty"`
	PortfolioURL    string `json:"portfolio_url,omitempty"`
	TwitterURL      string `json:"twitter_url,omitempty"`
	ResumeFileURL   string `json:"resume_file_url,omitempty"`
	CareerGapNote   string `json:"career_gap_note,omitempty"`
	ExperienceLevel string `json:"experience_level,omitempty"`
}

// AdminProfileView includes the persistence metadata the admin panel needs.
type AdminProfileView struct {
	ID              string    `json:"id"`
	FullName        string    `json:"full_name"`
	Title           string    `json:"title"`
	Tagline         string    `json:"tagline,omitempty"`
	Summary         string    `json:"summary,omitempty"`
	Email           string    `json:"email"`
	Phone           string    `json:"phone,omitempty"`
	Location        string    `json:"location,omitempty"`
	AvatarURL       string    `json:"avatar_url,omitempty"`
	LinkedinURL     string    `json:"linkedin_url,omitempty"`
	GithubURL       string    `json:"github_url,omitempty"`
	PortfolioURL    string    `json:"portfolio_url,omitempty"`
	TwitterURL      string    `json:"twitter_url,omitempty"`
	ResumeFileURL   string    `json:"resume_file_url,omitempty"`
	CareerGapNote   string    `json:"career_gap_note,omitempty"`
	ExperienceLevel string    `json:"experience_level,omitempty"`
	UpdatedAt       time.Time `json:"updated_at"`
}

// PublicProfile returns the profile rendered on the public site.
func (s *ProfileService) PublicProfile(ctx context.Context) (*PublicProfileView, error) {
	profile, err := s.profiles.Find(ctx)
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			return nil, errProfileNotFound()
		}
		return nil, err
	}
	return publicProfileView(profile), nil
}

// AdminProfile returns the profile with persistence metadata for the panel.
func (s *ProfileService) AdminProfile(ctx context.Context) (*AdminProfileView, error) {
	profile, err := s.profiles.Find(ctx)
	if err != nil {
		if errors.Is(err, models.ErrNotFound) {
			return nil, errProfileNotFound()
		}
		return nil, err
	}
	return adminProfileView(profile), nil
}

// UpdateProfile creates the singleton profile on first save and fully replaces
// its editable fields on later saves.
func (s *ProfileService) UpdateProfile(ctx context.Context, in ProfileInput) (*AdminProfileView, error) {
	in = normalizeProfileInput(in)
	if in.FullName == "" {
		return nil, errProfileValidation("full_name")
	}
	if in.Title == "" {
		return nil, errProfileValidation("title")
	}
	if in.Email == "" {
		return nil, errProfileValidation("email")
	}

	profile, err := s.profiles.Find(ctx)
	switch {
	case err == nil:
		// Keep the existing primary key and singleton marker.
	case errors.Is(err, models.ErrNotFound):
		profile = &models.Profile{ID: ids.New(), SingletonKey: singletonProfileKey}
	default:
		return nil, err
	}

	profile.FullName = in.FullName
	profile.Title = in.Title
	profile.Tagline = in.Tagline
	profile.Summary = in.Summary
	profile.Email = in.Email
	profile.Phone = in.Phone
	profile.Location = in.Location
	profile.AvatarURL = in.AvatarURL
	profile.LinkedinURL = in.LinkedinURL
	profile.GithubURL = in.GithubURL
	profile.PortfolioURL = in.PortfolioURL
	profile.TwitterURL = in.TwitterURL
	profile.ResumeFileURL = in.ResumeFileURL
	profile.CareerGapNote = in.CareerGapNote
	profile.ExperienceLevel = in.ExperienceLevel
	profile.UpdatedAt = s.now()

	if err := s.profiles.Upsert(ctx, profile); err != nil {
		return nil, err
	}
	return adminProfileView(profile), nil
}

func normalizeProfileInput(in ProfileInput) ProfileInput {
	in.FullName = strings.TrimSpace(in.FullName)
	in.Title = strings.TrimSpace(in.Title)
	in.Tagline = strings.TrimSpace(in.Tagline)
	in.Summary = strings.TrimSpace(in.Summary)
	in.Email = strings.ToLower(strings.TrimSpace(in.Email))
	in.Phone = strings.TrimSpace(in.Phone)
	in.Location = strings.TrimSpace(in.Location)
	in.AvatarURL = strings.TrimSpace(in.AvatarURL)
	in.LinkedinURL = strings.TrimSpace(in.LinkedinURL)
	in.GithubURL = strings.TrimSpace(in.GithubURL)
	in.PortfolioURL = strings.TrimSpace(in.PortfolioURL)
	in.TwitterURL = strings.TrimSpace(in.TwitterURL)
	in.ResumeFileURL = strings.TrimSpace(in.ResumeFileURL)
	in.CareerGapNote = strings.TrimSpace(in.CareerGapNote)
	in.ExperienceLevel = strings.TrimSpace(in.ExperienceLevel)
	return in
}

func publicProfileView(p *models.Profile) *PublicProfileView {
	return &PublicProfileView{
		FullName:        p.FullName,
		Title:           p.Title,
		Tagline:         p.Tagline,
		Summary:         p.Summary,
		Email:           p.Email,
		Phone:           p.Phone,
		Location:        p.Location,
		AvatarURL:       p.AvatarURL,
		LinkedinURL:     p.LinkedinURL,
		GithubURL:       p.GithubURL,
		PortfolioURL:    p.PortfolioURL,
		TwitterURL:      p.TwitterURL,
		ResumeFileURL:   p.ResumeFileURL,
		CareerGapNote:   p.CareerGapNote,
		ExperienceLevel: p.ExperienceLevel,
	}
}

func adminProfileView(p *models.Profile) *AdminProfileView {
